-- Create "billing_object_connections" table
CREATE TABLE "billing_object_connections" ("organization_id" uuid NOT NULL, "id" uuid NOT NULL, "subscription_id" uuid NULL, "wallet_id" uuid NULL, "recurring_transaction_rule_id" uuid NULL, "category" text NOT NULL, "behavior" text NOT NULL, "payment_provider_customer_id" uuid NULL, "integration_customer_id" uuid NULL, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, PRIMARY KEY ("organization_id", "id"), CONSTRAINT "billing_object_connections_integration_customer_fkey" FOREIGN KEY ("organization_id", "integration_customer_id") REFERENCES "integration_customers" ("organization_id", "id") ON UPDATE NO ACTION ON DELETE CASCADE, CONSTRAINT "billing_object_connections_organization_fkey" FOREIGN KEY ("organization_id") REFERENCES "organizations" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "billing_object_connections_payment_provider_customer_fkey" FOREIGN KEY ("organization_id", "payment_provider_customer_id") REFERENCES "payment_provider_customers" ("organization_id", "id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "billing_object_connections_rule_fkey" FOREIGN KEY ("organization_id", "recurring_transaction_rule_id") REFERENCES "recurring_transaction_rules" ("organization_id", "id") ON UPDATE NO ACTION ON DELETE CASCADE, CONSTRAINT "billing_object_connections_subscription_fkey" FOREIGN KEY ("organization_id", "subscription_id") REFERENCES "subscriptions" ("organization_id", "id") ON UPDATE NO ACTION ON DELETE CASCADE, CONSTRAINT "billing_object_connections_wallet_fkey" FOREIGN KEY ("organization_id", "wallet_id") REFERENCES "wallets" ("organization_id", "id") ON UPDATE NO ACTION ON DELETE CASCADE, CONSTRAINT "billing_object_connections_behavior_check" CHECK (behavior = ANY (ARRAY['specific'::text, 'skip'::text])), CONSTRAINT "billing_object_connections_category_check" CHECK (category = ANY (ARRAY['payment'::text, 'tax'::text, 'accounting'::text, 'crm'::text])), CONSTRAINT "billing_object_connections_connection_check" CHECK (((payment_provider_customer_id IS NOT NULL) = ((behavior = 'specific'::text) AND (category = 'payment'::text))) AND ((integration_customer_id IS NOT NULL) = ((behavior = 'specific'::text) AND (category <> 'payment'::text)))), CONSTRAINT "billing_object_connections_owner_check" CHECK (num_nonnulls(subscription_id, wallet_id, recurring_transaction_rule_id) = 1));
-- Create index "billing_object_connections_integration_customer_idx" to table: "billing_object_connections"
CREATE INDEX "billing_object_connections_integration_customer_idx" ON "billing_object_connections" ("organization_id", "integration_customer_id") WHERE (integration_customer_id IS NOT NULL);
-- Create index "billing_object_connections_payment_provider_customer_idx" to table: "billing_object_connections"
CREATE INDEX "billing_object_connections_payment_provider_customer_idx" ON "billing_object_connections" ("organization_id", "payment_provider_customer_id") WHERE (payment_provider_customer_id IS NOT NULL);
-- Create index "billing_object_connections_rule_key" to table: "billing_object_connections"
CREATE UNIQUE INDEX "billing_object_connections_rule_key" ON "billing_object_connections" ("organization_id", "recurring_transaction_rule_id", "category") WHERE (recurring_transaction_rule_id IS NOT NULL);
-- Create index "billing_object_connections_subscription_key" to table: "billing_object_connections"
CREATE UNIQUE INDEX "billing_object_connections_subscription_key" ON "billing_object_connections" ("organization_id", "subscription_id", "category") WHERE (subscription_id IS NOT NULL);
-- Create index "billing_object_connections_wallet_key" to table: "billing_object_connections"
CREATE UNIQUE INDEX "billing_object_connections_wallet_key" ON "billing_object_connections" ("organization_id", "wallet_id", "category") WHERE (wallet_id IS NOT NULL);
-- Enable row-level security on table "billing_object_connections"
ALTER TABLE billing_object_connections ENABLE ROW LEVEL SECURITY;
-- Create policy "tenant_isolation" on table "billing_object_connections"
CREATE POLICY tenant_isolation ON billing_object_connections AS PERMISSIVE FOR ALL TO public USING (((organization_id = (NULLIF(NULLIF(current_setting('tanvo.organization_id'::text, true), ''::text), '*'::text))::uuid) OR (current_setting('tanvo.organization_id'::text, true) = '*'::text)));
